Rules.InvariantScript:
If(
    Host.OSType = "Windows" And varControleIndex = true,
    Set(
        var_usuarioID,
        Param("USUARIO")
    );
    If(
        Mid(
            Param("LOGADO"),
            13,
            8
        ) = Text(
            Now(),
            "ddmmyyyy"
        ),
        UpdateContext({var_visibleErro: false}),
        UpdateContext({var_visibleErro: true})
    ),
    If(
        IsBlank(
            LookUp(
                User,
                Email = User().Email
            )
        ),
        UpdateContext({var_visibleContaErro: true}),
        UpdateContext({var_visibleContaErro: false})
    )
);
UpdateContext({var_visibleErro: false})

If(
    Host.OSType = "Windows",
    Launch(
        "https://apps.powerapps.com/play/providers/Microsoft.PowerApps/apps/a5af3add-12da-4107-b027-23daea7b0056?hideNavBar=true",
        {
            LOGADO: "z0x9c8v7b6n5" & Text(
                Now(),
                "ddmmyyyy"
            ) & Rand() * 100,
            USUARIO: varIdUser
        },
        LaunchTarget.Replace
    ),
    Exit()
